CREATE TRIGGER implementation_specs_no_delete BEFORE DELETE ON implementation_specs BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER policy_specs_no_update BEFORE UPDATE ON policy_specs BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER policy_specs_no_delete BEFORE DELETE ON policy_specs BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registries_no_update BEFORE UPDATE ON registries BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registries_no_delete BEFORE DELETE ON registries BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER policy_activations_no_update BEFORE UPDATE ON policy_activations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER policy_activations_no_delete BEFORE DELETE ON policy_activations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER logical_sources_no_update BEFORE UPDATE ON logical_sources BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER logical_sources_no_delete BEFORE DELETE ON logical_sources BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registrations_no_update BEFORE UPDATE ON registrations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registrations_no_delete BEFORE DELETE ON registrations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registration_observations_no_update BEFORE UPDATE ON registration_observations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER registration_observations_no_delete BEFORE DELETE ON registration_observations BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT, 'immutable ledger history'); END;
